    },
    [] => println("Usage: program <filename>")
  }
}

module benchmark/solution
import std/fs (readFile, writeFile)
import std/json (Json, decode, encode, jo, ja, kv, js, jnum, getString, getInt, getStringArrayOrEmpty)
import std/list (length as listLength)
import std/string (chars)
import std/option (Some, None)
import std/result (Ok, Err)

type Config = Config({app_name: string, version: string, port: int, features: [string]})
type LoadResult = LoadOk(Config) | LoadErr(string)

pure func countDotsChars(cs: [string]) -> int =
  match cs {
    [] => 0,
    c :: rest => if c == "." then 1 + countDotsChars(rest) else countDotsChars(rest)
  }

pure func countDots(s: string) -> int =
  countDotsChars(chars(s))

pure func validPort(port: int) -> bool =
  port >= 1024 && port <= 65535

pure func validVersion(version: string) -> bool =
  countDots(version) == 2

pure func validateConfig(appName: string, version: string, port: int, features: [string]) -> LoadResult {
  if not validPort(port) then LoadErr("Invalid port")
  else if not validVersion(version) then LoadErr("Invalid version")
  else if listLength(features) == 0 then LoadErr("Features list is empty")
  else LoadOk(Config({app_name: appName, version: version, port: port, features: features}))
}

pure func parseConfig(json: Json) -> LoadResult =
  match getString(json, "app_name") {
    Some(appName) => match getString(json, "version") {
      Some(version) => match getInt(json, "port") {
        Some(port) => {
          let features = getStringArrayOrEmpty(json, "features");
          validateConfig(appName, version, port, features)
        },
        None => LoadErr("Missing port")
      },
      None => LoadErr("Missing version")
    },
    None => LoadErr("Missing app_name")
  }

func loadConfig() -> LoadResult ! {FS} {
  let content = readFile("app_config.json");
  match decode(content) {
    Ok(json) => parseConfig(json),
    Err(msg) => LoadErr("Parse error: ${msg}")
  }
}

pure func configJson() -> string =
  encode(jo([
    kv("app_name", js("MyApp")),
    kv("version", js("1.0.0")),
    kv("port", jnum(8080.0)),
    kv("features", ja([js("logging"), js("auth"), js("api")]))
  ]))

export func main() -> () ! {IO, FS} {
  writeFile("app_config.json", configJson());
  match loadConfig() {
    LoadOk(config) => println("Loaded ${config.app_name} v${config.version} on port ${config.port} with ${listLength(config.features)} features"),
    LoadErr(msg) => println("Error: ${msg}")
  }
}

