import json
from pathlib import Path


CONFIG_FILE = "app_config.json"


def create_config() -> None:
    config = {
        "app_name": "MyApp",
        "version": "1.0.0",
        "port": 8080,
        "features": ["logging", "auth", "api"],
    }
    Path(CONFIG_FILE).write_text(json.dumps(config, indent=2))


def validate_config(config: dict) -> dict:
    if "port" not in config or not isinstance(config["port"], int):
        raise ValueError("port must be an integer")
    if not 1024 <= config["port"] <= 65535:
        raise ValueError(f"port {config['port']} must be between 1024 and 65535")

    version = config.get("version", "")
    if version.count(".") != 2:
        raise ValueError(f"version '{version}' must be in X.Y.Z format")

    if "features" not in config or not isinstance(config["features"], list):
        raise ValueError("features must be a list")
    if not config["features"]:
        raise ValueError("features list must not be empty")

    return config


def load_and_validate_config() -> dict:
    content = Path(CONFIG_FILE).read_text()
    data = json.loads(content)
    return validate_config(data)


def main() -> None:
    create_config()
    config = load_and_validate_config()
    print(
        f"Loaded {config['app_name']} v{config['version']} "
        f"on port {config['port']} with {len(config['features'])} features"
    )


if __name__ == "__main__":
    main()

