from __future__ import annotations

from dataclasses import dataclass


class _Leaf:
    _instance: _Leaf | None = None

    def __new__(cls) -> _Leaf:
        if cls._instance is None:
            cls._instance = super().__new__(cls)
        return cls._instance

    def __repr__(self) -> str:
        return "Leaf"


Leaf = _Leaf()


@dataclass
class Node:
    value: int
    left: Tree
    right: Tree


type Tree = Node | _Leaf


def size(tree: Tree) -> int:
    match tree:
        case _Leaf():
            return 0
        case Node(value=_, left=left, right=right):
            return 1 + size(left) + size(right)


def contains(tree: Tree, x: int) -> bool:
    match tree:
        case _Leaf():
            return False
        case Node(value=v, left=left, right=right):
            if x < v:
                return contains(left, x)
            if x > v:
                return contains(right, x)
            return True


def insert(tree: Tree, x: int) -> Tree:
    match tree:
        case _Leaf():
            return Node(value=x, left=Leaf, right=Leaf)
        case Node(value=v, left=left, right=right):
            if x < v:
                return Node(value=v, left=insert(left, x), right=right)
            if x > v:
                return Node(value=v, left=left, right=insert(right, x))
            return tree


def isBST(tree: Tree, lo: int, hi: int) -> bool:
    match tree:
        case _Leaf():
            return True
        case Node(value=v, left=left, right=right):
            if v <= lo or v >= hi:
                return False
            return isBST(left, lo, v) and isBST(right, v, hi)


def insertPreservesBST(x: int) -> bool:
    tree = Leaf
    tree = insert(tree, x)
    return isBST(tree, -999999, 999999)


def insertThenFind(x: int) -> bool:
    tree = Leaf
    tree = insert(tree, x)
    return contains(tree, x)


def main() -> None:
    tree = insert(insert(insert(Leaf, 5), 3), 7)
    print(size(tree))
    print(str(contains(tree, 3)).lower())
    print(str(contains(tree, 4)).lower())
    print(str(isBST(tree, -999999, 999999)).lower())
    print(str(insertPreservesBST(42)).lower())
    print(str(insertThenFind(42)).lower())


if __name__ == "__main__":
    main()

