module benchmark/solution
import std/string (chars, stringToInt, charCode)
import std/option (Some, None)

func isDigit(c: string) -> bool {
  let code = charCode(c);
  code >= 48 && code <= 57
}

func repeatChar(c: string, n: int) -> string =
  if n <= 0 then "" else "${c}${repeatChar(c, n - 1)}"

func parseCount(s: string) -> int =
  match stringToInt(s) {
    Some(n) => n,
    None => 0
  }

func encodeRun(current: string, count: int, rest: [string]) -> string =
  match rest {
    [] => "${show(count)}${current}",
    x :: xs => if x == current then encodeRun(current, count + 1, xs) else "${show(count)}${current}${encodeRun(x, 1, xs)}"
  }

func encodeChars(cs: [string]) -> string =
  match cs {
    [] => "",
    c :: rest => encodeRun(c, 1, rest)
  }

export func encode(s: string) -> string =
  encodeChars(chars(s))

func decodeChars(cs: [string], digits: string) -> string =
  match cs {
    [] => "",
    c :: rest => if isDigit(c) then decodeChars(rest, "${digits}${c}") else "${repeatChar(c, parseCount(digits))}${decodeChars(rest, "")}"
  }

export func decode(s: string) -> string =
  decodeChars(chars(s), "")

export func roundtrip(s: string) -> bool =
  decode(encode(s)) == s

export func singleCharEncode(c: string) -> bool =
  encode(c) == "1${c}"

export func main() -> () ! {IO} {
  println(encode("aaabbc"));
  println(encode("xyz"));
  println(decode("3a2b1c"));
  println(decode("1x1y1z"));
  println(show(roundtrip("hello")));
  println(show(singleCharEncode("q")))
}

