def encode(s: str) -> str:
    if not s:
        return ""
    parts = []
    i = 0
    n = len(s)
    while i < n:
        ch = s[i]
        count = 1
        while i + count < n and s[i + count] == ch:
            count += 1
        parts.append(f"{count}{ch}")
        i += count
    return "".join(parts)


def decode(s: str) -> str:
    if not s:
        return ""
    parts = []
    i = 0
    n = len(s)
    while i < n:
        j = i
        while j < n and s[j].isdigit():
            j += 1
        count = int(s[i:j])
        ch = s[j]
        parts.append(ch * count)
        i = j + 1
    return "".join(parts)


def roundtrip(s: str) -> bool:
    return decode(encode(s)) == s


def singleCharEncode(s: str) -> bool:
    return encode(s) == f"1{s}"


def main() -> None:
    print(encode("aaabbc"))
    print(encode("xyz"))
    print(decode("3a2b1c"))
    print(decode("1x1y1z"))
    print(str(roundtrip("hello")).lower())
    print(str(singleCharEncode("q")).lower())


if __name__ == "__main__":
    main()

