module benchmark/solution
import std/string (chars)

pure func romanValue(c: string) -> int =
  if c == "I" then 1
  else if c == "V" then 5
  else if c == "X" then 10
  else if c == "L" then 50
  else if c == "C" then 100
  else if c == "D" then 500
  else if c == "M" then 1000
  else 0

pure func parseRoman(cs: [string]) -> int =
  match cs {
    [] => 0,
    c :: rest => match rest {
      [] => romanValue(c),
      next :: tail => {
        let v = romanValue(c);
        let nv = romanValue(next);
        if v < nv then (nv - v) + parseRoman(tail) else v + parseRoman(rest)
      }
    }
  }

export pure func fromRoman(s: string) -> int =
  parseRoman(chars(s))

export pure func toRoman(n: int) -> string =
  if n >= 1000 then "M${toRoman(n - 1000)}"
  else if n >= 900 then "CM${toRoman(n - 900)}"
  else if n >= 500 then "D${toRoman(n - 500)}"
  else if n >= 400 then "CD${toRoman(n - 400)}"
  else if n >= 100 then "C${toRoman(n - 100)}"
  else if n >= 90 then "XC${toRoman(n - 90)}"
  else if n >= 50 then "L${toRoman(n - 50)}"
  else if n >= 40 then "XL${toRoman(n - 40)}"
  else if n >= 10 then "X${toRoman(n - 10)}"
  else if n >= 9 then "IX${toRoman(n - 9)}"
  else if n >= 5 then "V${toRoman(n - 5)}"
  else if n >= 4 then "IV${toRoman(n - 4)}"
  else if n >= 1 then "I${toRoman(n - 1)}"
  else ""

export pure func roundtrip(n: int) -> bool =
  if n >= 1 && n <= 3999 then fromRoman(toRoman(n)) == n else true

export pure func distinctEncoding(a: int, b: int) -> bool =
  if a >= 1 && a <= 3999 && b >= 1 && b <= 3999 && a != b then toRoman(a) != toRoman(b) else true

export func main() -> () ! {IO} {
  println(toRoman(1994));
  println(toRoman(58));
  println(toRoman(3999));
  println(show(fromRoman("MCMXCIV")));
  println(show(fromRoman("LVIII")));
  println(show(roundtrip(2024)));
  println(show(distinctEncoding(4, 6)))
}

