ROMAN_VALUES = [
    (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
    (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
    (10, "X"), (9, "IX"), (5, "V"), (4, "IV"),
    (1, "I"),
]

ROMAN_MAP = {s: v for v, s in ROMAN_VALUES}
ROMAN_MAP.update({c: ROMAN_MAP[c] for c in "IVXLCDM"})


def toRoman(n: int) -> str:
    result = []
    for value, numeral in ROMAN_VALUES:
        while n >= value:
            result.append(numeral)
            n -= value
    return "".join(result)


def fromRoman(s: str) -> int:
    i = 0
    total = 0
    while i < len(s):
        if i + 1 < len(s) and s[i:i+2] in ROMAN_MAP:
            total += ROMAN_MAP[s[i:i+2]]
            i += 2
        else:
            total += ROMAN_MAP[s[i]]
            i += 1
    return total


def roundtrip(n: int) -> bool:
    return fromRoman(toRoman(n)) == n


def distinctEncoding(a: int, b: int) -> bool:
    return toRoman(a) != toRoman(b)


def main() -> None:
    print(toRoman(1994))
    print(toRoman(58))
    print(toRoman(3999))
    print(fromRoman("MCMXCIV"))
    print(fromRoman("LVIII"))
    print(str(roundtrip(2024)).lower())
    print(str(distinctEncoding(4, 6)).lower())


if __name__ == "__main__":
    main()

