module benchmark/solution

export type SSet = SNil | SCons(int, SSet)

export func sLength(s: SSet) -> int =
  match s {
    SNil => 0,
    SCons(_, rest) => 1 + sLength(rest)
  }

export func isSorted(s: SSet) -> bool =
  match s {
    SNil => true,
    SCons(x, rest) => match rest {
      SNil => true,
      SCons(y, _) => x < y && isSorted(rest)
    }
  }

export func sInsert(x: int, s: SSet) -> SSet =
  match s {
    SNil => SCons(x, SNil),
    SCons(y, ys) =>
      if x < y then SCons(x, s)
      else if x == y then s
      else SCons(y, sInsert(x, ys))
  }

export func normalize(s: SSet) -> SSet =
  match s {
    SNil => SNil,
    SCons(x, rest) => sInsert(x, normalize(rest))
  }

func mergeSorted(a: SSet, b: SSet) -> SSet =
  match a {
    SNil => b,
    SCons(x, xs) => match b {
      SNil => a,
      SCons(y, ys) =>
        if x < y then SCons(x, mergeSorted(xs, b))
        else if x > y then SCons(y, mergeSorted(a, ys))
        else SCons(x, mergeSorted(xs, ys))
    }
  }

func intersectSorted(a: SSet, b: SSet) -> SSet =
  match a {
    SNil => SNil,
    SCons(x, xs) => match b {
      SNil => SNil,
      SCons(y, ys) =>
        if x < y then intersectSorted(xs, b)
        else if x > y then intersectSorted(a, ys)
        else SCons(x, intersectSorted(xs, ys))
    }
  }

export func sMerge(a: SSet, b: SSet) -> SSet =
  mergeSorted(normalize(a), normalize(b))

export func sIntersect(a: SSet, b: SSet) -> SSet =
  intersectSorted(normalize(a), normalize(b))

export func sContains(x: int, s: SSet) -> bool =
  match s {
    SNil => false,
    SCons(y, ys) =>
      if x == y then true
      else if x < y then false
      else sContains(x, ys)
  }

func toStrParts(s: SSet) -> string =
  match s {
    SNil => "",
    SCons(x, rest) => match rest {
      SNil => show(x),
      SCons(_, _) => "${show(x)}, ${toStrParts(rest)}"
    }
  }

export func toStr(s: SSet) -> string =
  "{${toStrParts(s)}}"

export func mergePreservesSorted(a: SSet, b: SSet) -> bool =
  isSorted(sMerge(a, b))

export func intersectPreservesSorted(a: SSet, b: SSet) -> bool =
  isSorted(sIntersect(a, b))

export func inclusionExclusion(a: SSet, b: SSet) -> bool {
  let left = sLength(sMerge(a, b)) + sLength(sIntersect(a, b));
  let right = sLength(normalize(a)) + sLength(normalize(b));
  left == right
}

export func main() -> () ! {IO} {
  let a = SCons(1, SCons(3, SCons(5, SNil)));
  let b = SCons(2, SCons(3, SCons(4, SNil)));
  println(toStr(sMerge(a, b)));
  println(toStr(sIntersect(a, b)));
  println(show(sLength(sMerge(a, b))));
  println(show(isSorted(sMerge(a, b))));
  println(show(mergePreservesSorted(a, b)));
  println(show(inclusionExclusion(a, b)))
}

