class SNil:
    pass


class SCons:
    def __init__(self, head, tail):
        self.head = head
        self.tail = tail


def toStr(s):
    parts = []
    while isinstance(s, SCons):
        parts.append(str(s.head))
        s = s.tail
    return "[" + ",".join(parts) + "]"


def sLength(s):
    n = 0
    while isinstance(s, SCons):
        n += 1
        s = s.tail
    return n


def isSorted(s):
    prev = None
    while isinstance(s, SCons):
        if prev is not None and s.head <= prev:
            return False
        prev = s.head
        s = s.tail
    return True


def sMerge(a, b):
    if isinstance(a, SNil):
        return b
    if isinstance(b, SNil):
        return a
    if a.head < b.head:
        return SCons(a.head, sMerge(a.tail, b))
    if a.head > b.head:
        return SCons(b.head, sMerge(a, b.tail))
    return SCons(a.head, sMerge(a.tail, b.tail))


def sIntersect(a, b):
    if isinstance(a, SNil) or isinstance(b, SNil):
        return SNil()
    if a.head < b.head:
        return sIntersect(a.tail, b)
    if a.head > b.head:
        return sIntersect(a, b.tail)
    return SCons(a.head, sIntersect(a.tail, b.tail))


def mergePreservesSorted(a, b):
    return isSorted(a) and isSorted(b) and isSorted(sMerge(a, b))


def inclusionExclusion(a, b):
    return sLength(sMerge(a, b)) + sLength(sIntersect(a, b)) == sLength(a) + sLength(b)


def toBoolStr(b):
    return "true" if b else "false"


def main():
    a = SCons(1, SCons(3, SCons(5, SNil())))
    b = SCons(2, SCons(3, SCons(4, SNil())))
    print(toStr(sMerge(a, b)))
    print(toStr(sIntersect(a, b)))
    print(sLength(sMerge(a, b)))
    print(toBoolStr(isSorted(sMerge(a, b))))
    print(toBoolStr(mergePreservesSorted(a, b)))
    print(toBoolStr(inclusionExclusion(a, b)))


