import std/fs (writeFile, readFile)
import std/string (split, trim, stringToInt, find)
import std/json (encode, jo, ja, kv, js, jnum, Json)
import std/io (println)
import std/option (Option, Some, None)
import std/list (length, reverse)
import std/math (intToFloat)

type Row = {name: string, age: int, email: string}

pure func validAge(ageStr: string) -> Option[int] {
  match stringToInt(trim(ageStr)) {
    Some(a) => if a > 0 then Some(a) else None,
    None => None
  }
}

pure func validEmail(emailStr: string) -> bool {
  find(emailStr, "@") != -1
}

pure func parseRow(fields: [string]) -> Option[Row] {
  match fields {
    [name, ageStr, email] => {
      match validAge(ageStr) {
        Some(a) => if validEmail(email) then Some({name: trim(name), age: a, email: trim(email)}) else None,
        None => None
      }
    },
    _ => None
  }
}

pure func parseCSV(content: string) -> [Row] {
  let lines = split(content, "\n");
  match lines {
    headerLine :: dataLines => {
      letrec process = \lines acc.
        match lines {
          [] => reverse(acc),
          "" :: rest => process(rest, acc),
          line :: rest => {
            let fields = split(line, ",");
            match parseRow(fields) {
              Some(row) => process(rest, row :: acc),
              None => process(rest, acc)
            }
          }
        };
      process(dataLines, [])
    },
    _ => []
  }
}

pure func rowToJson(r: Row) -> Json {
  jo([kv("name", js(r.name)), kv("age", jnum(intToFloat(r.age))), kv("email", js(r.email))])
}

pure func rowsToJsonArray(rows: [Row]) -> string {
  letrec mapRows = \rs acc.
    match rs {
      [] => reverse(acc),
      r :: rest => mapRows(rest, rowToJson(r) :: acc)
    };
  let jsonList = mapRows(rows, []);
  encode(ja(jsonList))
}

export func main() -> () ! {IO, FS} {
  let csvContent = "name,age,email\nAlice,30,alice@example.com\nBob,25,bob@example.com\nCarol,35,carol@example.com\n";
  writeFile("users.csv", csvContent);

  let content = readFile("users.csv");
  let rows = parseCSV(content);
  let validCount = length(rows);

  let jsonStr = rowsToJsonArray(rows);
  writeFile("users.json", jsonStr);

  println("Converted ${show(validCount)} valid rows to users.json")
}

