module benchmark/solution

pure func contains(x: int, xs: [int]) -> bool =
  match xs {
    [] => false,
    y :: rest => if x == y then true else contains(x, rest)
  }

pure func enqueue(x: int, queue: [int]) -> [int] =
  match queue {
    [] => [x],
    y :: rest => y :: enqueue(x, rest)
  }

pure func enqueueAll(xs: [int], queue: [int]) -> [int] =
  match xs {
    [] => queue,
    x :: rest => enqueueAll(rest, enqueue(x, queue))
  }

pure func neighbors(graph: [(int, [int])], node: int) -> [int] =
  match graph {
    [] => [],
    (n, ns) :: rest => if n == node then ns else neighbors(rest, node)
  }

pure func bfsLoop(graph: [(int, [int])], queue: [int], visited: [int]) -> [int] =
  match queue {
    [] => visited,
    node :: rest => {
      if contains(node, visited) then bfsLoop(graph, rest, visited)
      else {
        let ns = neighbors(graph, node);
        let nextQueue = enqueueAll(ns, rest);
        let nextVisited = enqueue(node, visited);
        bfsLoop(graph, nextQueue, nextVisited)
      }
    }
  }

export func bfs(graph: [(int, [int])], start: int) -> [int] =
  bfsLoop(graph, [start], [])

