def bfs(graph, start):
    queue = []
    visited = []
    enqueue(start, queue)

    while queue:
        node = queue.pop(0)
        if contains(node, visited):
            continue
        visited.append(node)
        for neighbor in graph[node]:
            if not contains(neighbor, visited):
                enqueue(neighbor, queue)

    return visited


