module benchmark/solution

import std/fs (writeFile, readFile)
import std/string (split, trim, contains, find, substring, length)
import std/list (filter, length as listLength, foldl, sortBy)
import std/option (Option, Some, None)

func writeLog() -> () ! {FS} {
  let content = "2024-10-29 10:00:00 INFO User logged in: alice\n2024-10-29 10:01:15 ERROR Database connection failed\n2024-10-29 10:02:30 INFO User logged in: bob\n2024-10-29 10:03:45 WARNING High memory usage: 85%\n2024-10-29 10:05:00 ERROR API timeout: /users endpoint\n2024-10-29 10:06:15 INFO User logged out: alice\n";
  writeFile("app.log", content)
}

func getLevel(line: string) -> string {
  let parts = split(line, " ");
  match parts {
    _ :: _ :: lvl :: _ => lvl,
    _ => ""
  }
}

func countLevel(lines: [string], lvl: string) -> int {
  let matched = filter(\l. getLevel(l) == lvl, lines);
  listLength(matched)
}

func extractUser(line: string) -> string {
  if contains(line, "User logged") then {
    let idx = find(line, ": ");
    if idx >= 0 then trim(substring(line, idx + 2, length(line)))
    else ""
  } else ""
}

func memberStr(xs: [string], s: string) -> bool {
  match xs {
    [] => false,
    x :: rest => if x == s then true else memberStr(rest, s)
  }
}

func collectUsers(lines: [string], acc: [string]) -> [string] {
  match lines {
    [] => acc,
    l :: rest => {
      let u = extractUser(l);
      if u != "" && not memberStr(acc, u) then collectUsers(rest, acc ++ [u])
      else collectUsers(rest, acc)
    }
  }
}

func cmpStr(a: string, b: string) -> int {
  if a < b then 0 - 1 else if a > b then 1 else 0
}

func joinUsers(xs: [string]) -> string {
  match xs {
    [] => "",
    x :: [] => x,
    x :: rest => "${x}, ${joinUsers(rest)}"
  }
}

export func main() -> () ! {IO, FS} {
  writeLog();
  let content = readFile("app.log");
  let rawLines = split(content, "\n");
  let lines = filter(\l. trim(l) != "", rawLines);
  let total = listLength(lines);
  let info = countLevel(lines, "INFO");
  let error = countLevel(lines, "ERROR");
  let warning = countLevel(lines, "WARNING");
  let infoPct = (info * 100) / total;
  let errorPct = (error * 100) / total;
  let warningPct = (warning * 100) / total;
  let users = sortBy(cmpStr, collectUsers(lines, []));
  println("Total log entries: ${show(total)}");
  println("INFO: ${show(info)} (${show(infoPct)}%)");
