    left: "Expr"
    right: "Expr"


@dataclass
class Mul:
    left: "Expr"
    right: "Expr"


@dataclass
class Let:
    name: str
    expr: "Expr"
    body: "Expr"


Expr = Union[Num, Var, Add, Mul, Let]
Env = list[tuple[str, int]]


def lookup(name: str, env: Env) -> int:
    for n, v in reversed(env):
        if n == name:
            return v
    raise NameError(f"Undefined variable: {name}")


def eval(expr: Expr, env: Env) -> int:
    match expr:
        case Num(value):
            return value
        case Var(name):
            return lookup(name, env)
        case Add(left, right):
            return eval(left, env) + eval(right, env)
        case Mul(left, right):
            return eval(left, env) * eval(right, env)
        case Let(name, e, body):
            val = eval(e, env)
            return eval(body, [(name, val)] + env)


def main() -> None:
    program = Let("x", Num(5), Let("y", Add(Var("x"), Num(3)), Mul(Var("x"), Var("y"))))
