from dataclasses import dataclass
from typing import Union


@dataclass(frozen=True)
class Const:
    val: int


@dataclass(frozen=True)
class Var:
    name: str


@dataclass(frozen=True)
class Add:
    left: "Expr"
    right: "Expr"


@dataclass(frozen=True)
class Mul:
    left: "Expr"
    right: "Expr"


Expr = Const | Var | Add | Mul


def showExpr(expr: Expr) -> str:
    match expr:
        case Const(n):
            return str(n)
        case Var(name):
            return name
        case Add(left, right):
            return f"({showExpr(left)} + {showExpr(right)})"
        case Mul(left, right):
            return f"({showExpr(left)} * {showExpr(right)})"


def diff(expr: Expr, var: str) -> Expr:
    match expr:
        case Const(_):
            return Const(0)
        case Var(name):
            return Const(1) if name == var else Const(0)
        case Add(left, right):
            return Add(diff(left, var), diff(right, var))
        case Mul(left, right):
            return Add(Mul(left, diff(right, var)), Mul(right, diff(left, var)))


def simplify(expr: Expr) -> Expr:
    match expr:
        case Const(_):
            return expr
        case Var(_):
            return expr
        case Add(Const(0), right):
            return simplify(right)
        case Add(left, Const(0)):
            return simplify(left)
        case Add(left, right):
            sl = simplify(left)
            sr = simplify(right)
            match (sl, sr):
                case (Const(0), _):
                    return sr
                case (_, Const(0)):
                    return sl
                case _:
                    return Add(sl, sr)
        case Mul(Const(0), _):
            return Const(0)
        case Mul(_, Const(0)):
            return Const(0)
        case Mul(Const(1), right):
            return simplify(right)
        case Mul(left, Const(1)):
            return simplify(left)
        case Mul(left, right):
            sl = simplify(left)
            sr = simplify(right)
            match (sl, sr):
                case (Const(0), _):
                    return Const(0)
                case (_, Const(0)):
                    return Const(0)
                case (Const(1), _):
                    return sr
                case (_, Const(1)):
                    return sl
                case _:
                    return Mul(sl, sr)


def main() -> None:
    expr = Add(Add(Mul(Var("x"), Var("x")), Mul(Const(3), Var("x"))), Const(5))
    d = diff(expr, "x")
    s = simplify(d)
    print(showExpr(s))


if __name__ == "__main__":
    main()

