import std/option (Option, Some, None)

export type Type = TVar(string) | TInt | TBool | TFunc(Type, Type)

pure func lookup(subst: [(string, Type)], v: string) -> Type =
  match subst {
    [] => TVar(v),
    (name, tp) :: rest => if name == v then tp else lookup(rest, v)
  }

pure func apply(subst: [(string, Type)], t: Type) -> Type =
  match t {
    TVar(v) => lookup(subst, v),
    TInt => TInt,
    TBool => TBool,
    TFunc(a, r) => TFunc(apply(subst, a), apply(subst, r))
  }

pure func unify(t1: Type, t2: Type) -> Option[([(string, Type)])] =
  match (t1, t2) {
    (TInt, TInt) => Some([]),
    (TBool, TBool) => Some([]),
    (TVar(v), tp) => Some([(v, tp)]),
    (tp, TVar(v)) => Some([(v, tp)]),
    (TFunc(a1, r1), TFunc(a2, r2)) =>
      match unify(a1, a2) {
        Some(s1) => match unify(r1, r2) {
          Some(s2) => Some(s1 ++ s2),
          None => None
        },
        None => None
      },
    _ => None
  }

pure func showType(t: Type) -> string =
  match t {
    TVar(v) => v,
    TInt => "TInt",
    TBool => "TBool",
    TFunc(a, r) => "TFunc(${showType(a)}, ${showType(r)})"
  }

func printSubst(subst: [(string, Type)]) -> () ! {IO} =
  match subst {
    [] => (),
    (v, tp) :: rest => {
      println("${v} = ${showType(tp)}");
      printSubst(rest)
    }
  }

export func main() -> () ! {IO} {
  let t1 = TFunc(TVar("a"), TInt);
  let t2 = TFunc(TBool, TVar("b"));
  match unify(t1, t2) {
    Some(subst) => printSubst(subst),
    None => println("Unification failed")
  }
