from dataclasses import dataclass
from typing import Self


@dataclass
class Type:
    pass


@dataclass
class TVar(Type):
    name: str


@dataclass
class TInt(Type):
    pass


@dataclass
class TBool(Type):
    pass


@dataclass
class TFunc(Type):
    arg: Type
    result: Type


Subst = list[tuple[str, Type]]


def apply(subst: Subst, ty: Type) -> Type:
    match ty:
        case TVar(name):
            for var, t in subst:
                if var == name:
                    return t
            return ty
        case TFunc(arg, result):
            return TFunc(apply(subst, arg), apply(subst, result))
        case _:
            return ty


def unify(t1: Type, t2: Type) -> Subst:
    match (t1, t2):
        case (TInt(), TInt()):
            return []
        case (TBool(), TBool()):
            return []
        case (TVar(a), _):
            return [(a, t2)]
        case (_, TVar(a)):
            return [(a, t1)]
        case (TFunc(a1, r1), TFunc(a2, r2)):
            s1 = unify(a1, a2)
            s2 = unify(apply(s1, r1), apply(s1, r2))
            return s1 + s2
        case _:
            raise ValueError("Cannot unify")


def main() -> None:
    t1 = TFunc(TVar("a"), TInt())
    t2 = TFunc(TBool(), TVar("b"))

    subst = unify(t1, t2)
    result = {}

    for var, ty in subst:
        result[var] = ty

    for var in ("a", "b"):
        ty = result[var]
        match ty:
            case TVar(name):
                print(f"{var} = TVar({name})")
            case TInt():
                print(f"{var} = TInt")
            case TBool():
                print(f"{var} = TBool")
            case _:
                print(f"{var} = {ty}")


if __name__ == "__main__":
    main()
